#!/bin/sh
#
# Sing-box Service Check - установщик модуля проверки доступности сервисов.
#
# Скрипт самодостаточный: полезная нагрузка лежит внутри в base64.
# Поддерживаются Tachyon, HomeProxy, Forkop и оригинальный Podkop. Их файлы при установке
# модуля не изменяются; Forkop-фиксы доступны отдельно только на Forkop.
#
# Установка:   sh install-sing-box-service-check.sh
# Удаление:    sh install-sing-box-service-check.sh --uninstall
#

set -e

VERSION="1.15.0"
BUILT_AT="2026-09-25"

BIN_PATH="/usr/bin/sing-box-service-check"
LEGACY_BIN_PATH="/usr/bin/forkop-servicecheck"
LIB_DIR="/usr/lib/sing-box-service-check"
SHARE_DIR="/usr/share/sing-box-service-check"
VERSION_FILE="$SHARE_DIR/version"
VIEW_NAME="servicecheck-v1150.js"
VIEW_FILE="/www/luci-static/resources/view/sing-box-service-check/$VIEW_NAME"
OLD_CURRENT_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1141.js"
PREVIOUS_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1140.js"
OLDER_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1130.js"
ANCIENT_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1125.js"
HISTORIC_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1124.js"
LEGACY_CACHE_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1123.js"
OLDER_CACHE_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1122.js"
EARLY_CACHE_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1121.js"
OLDEST_CACHE_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-v1120.js"
LEGACY_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck.js"
BROKEN_VIEW_FILE="/www/luci-static/resources/view/forkop/servicecheck-1.1.0.js"
MENU_FILE="/usr/share/luci/menu.d/luci-app-sing-box-service-check.json"
ACL_FILE="/usr/share/rpcd/acl.d/luci-app-sing-box-service-check.json"
STATE_DIR="/var/run/sing-box-service-check"
MIGRATE_SCRIPT="$LIB_DIR/migrate.sh"
OLD_PACKAGE="luci-app-forkop-servicecheck"
NEW_PACKAGE="luci-app-sing-box-service-check"
OLD_LIB_DIR="/usr/lib/forkop-servicecheck"
OLD_SHARE_DIR="/usr/share/forkop-servicecheck"
OLD_MENU_FILE="/usr/share/luci/menu.d/luci-app-forkop-servicecheck.json"
OLD_ACL_FILE="/usr/share/rpcd/acl.d/luci-app-forkop-servicecheck.json"
NETNS_DIR="/etc/netns/sbsvcchk"
DEPENDENCY_MODE="prompt"

log() {
    printf '\033[0;36m[servicecheck]\033[0m %s\n' "$1"
}

fail() {
    printf '\033[0;31m[servicecheck]\033[0m %s\n' "$1" >&2
    exit 1
}

clear_luci_cache() {
    rm -rf /tmp/luci-modulecache 2>/dev/null || true
    rm -f /tmp/luci-indexcache* 2>/dev/null || true
}

reload_rpcd() {
    if [ -x /etc/init.d/rpcd ]; then
        /etc/init.d/rpcd restart >/dev/null 2>&1 || /etc/init.d/rpcd reload >/dev/null 2>&1 || true
    fi
}

# Эти две функции намеренно не содержат списка имён файлов: установка и
# транзакционный откат обязаны охватывать каждый runtime-файл из payload.
runtime_payload_paths() {
    runtime_source_dir="$1"
    runtime_target_dir="$2"
    for runtime_source in "$runtime_source_dir/"*; do
        [ -f "$runtime_source" ] || continue
        printf '%s/%s\n' "$runtime_target_dir" "${runtime_source##*/}"
    done
}

install_runtime_payload() {
    runtime_source_dir="$1"
    runtime_target_dir="$2"
    runtime_installed=0
    for runtime_source in "$runtime_source_dir/"*; do
        [ -f "$runtime_source" ] || continue
        runtime_destination="$runtime_target_dir/${runtime_source##*/}"
        cp -f "$runtime_source" "$runtime_destination"
        case "$runtime_destination" in
            *.sh) chmod 0755 "$runtime_destination" ;;
            *) chmod 0644 "$runtime_destination" ;;
        esac
        runtime_installed=$((runtime_installed + 1))
    done
    [ "$runtime_installed" -gt 0 ]
}

do_uninstall() {
    log "Удаляю модуль проверки сервисов"

    if [ -x "$BIN_PATH" ]; then
        "$BIN_PATH" netns_teardown >/dev/null 2>&1 || true
    elif [ -x "$LEGACY_BIN_PATH" ]; then
        "$LEGACY_BIN_PATH" netns_teardown >/dev/null 2>&1 || true
    fi

    if command -v opkg >/dev/null 2>&1; then
        for package in "$NEW_PACKAGE" "$OLD_PACKAGE"; do
            if opkg status "$package" 2>/dev/null | grep -q "^Status:.*installed"; then
                opkg remove "$package" || fail "Не удалось удалить пакет $package через opkg"
            fi
        done
    elif command -v apk >/dev/null 2>&1; then
        for package in "$NEW_PACKAGE" "$OLD_PACKAGE"; do
            if apk info -v "$package" 2>/dev/null | grep -q "^$package-[0-9]"; then
                apk del "$package" || fail "Не удалось удалить пакет $package через apk"
            fi
        done
    fi

    rm -f "$BIN_PATH" "$LEGACY_BIN_PATH" "$VIEW_FILE" "$OLD_CURRENT_VIEW_FILE" "$PREVIOUS_VIEW_FILE" "$OLDER_VIEW_FILE" "$ANCIENT_VIEW_FILE" "$HISTORIC_VIEW_FILE" "$LEGACY_CACHE_VIEW_FILE" "$OLDER_CACHE_VIEW_FILE" "$EARLY_CACHE_VIEW_FILE" "$OLDEST_CACHE_VIEW_FILE" "$LEGACY_VIEW_FILE" "$BROKEN_VIEW_FILE" "$MENU_FILE" "$ACL_FILE" "$OLD_MENU_FILE" "$OLD_ACL_FILE"
    rm -rf "$LIB_DIR" "$SHARE_DIR" "$STATE_DIR" "$NETNS_DIR" "$OLD_LIB_DIR" "$OLD_SHARE_DIR"

    clear_luci_cache
    reload_rpcd

    log "Готово. Страница пропадёт из меню после обновления вкладки LuCI."
    exit 0
}

case "$1" in
    --uninstall|uninstall|-u)
        do_uninstall
        ;;
    --install-missing)
        DEPENDENCY_MODE="install"
        ;;
    --skip-missing)
        DEPENDENCY_MODE="skip"
        ;;
esac

log "Sing-box Service Check $VERSION (собран $BUILT_AT)"

detect_installed_version() {
    if [ -s "$VERSION_FILE" ]; then
        head -n 1 "$VERSION_FILE"
        return
    fi

    if command -v opkg >/dev/null 2>&1; then
        PACKAGE_VERSION="$(opkg status "$NEW_PACKAGE" 2>/dev/null |
            sed -n 's/^Version: //p' | head -n 1)"
        if [ -z "$PACKAGE_VERSION" ]; then
            PACKAGE_VERSION="$(opkg status "$OLD_PACKAGE" 2>/dev/null | sed -n 's/^Version: //p' | head -n 1)"
        fi
        if [ -n "$PACKAGE_VERSION" ]; then
            printf '%s\n' "$PACKAGE_VERSION"
            return
        fi
    fi

    if command -v apk >/dev/null 2>&1 &&
        apk info -e "$NEW_PACKAGE" >/dev/null 2>&1; then
        apk info -v "$NEW_PACKAGE" 2>/dev/null | head -n 1
        return
    fi

    if command -v apk >/dev/null 2>&1 && apk info -v "$OLD_PACKAGE" 2>/dev/null | grep -q "^$OLD_PACKAGE-[0-9]"; then
        apk info -v "$OLD_PACKAGE" 2>/dev/null | grep "^$OLD_PACKAGE-[0-9]" | head -n 1
        return
    fi

    if [ -x "$BIN_PATH" ] || [ -x "$LEGACY_BIN_PATH" ]; then
        printf '%s\n' "legacy (без маркера версии)"
    fi
}

detect_update_dependencies() {
    BIND_DEPENDENCY_STATE="ok"
    BIND_DEPENDENCY_PACKAGES=""

    if ! command -v dig >/dev/null 2>&1; then
        BIND_DEPENDENCY_STATE="missing"
        BIND_DEPENDENCY_PACKAGES="bind-dig"
    elif ! dig -v >/dev/null 2>&1; then
        BIND_DEPENDENCY_STATE="repair"
        BIND_DEPENDENCY_PACKAGES="bind-libs bind-dig"
    fi
}

dependency_install_hint() {
    if command -v opkg >/dev/null 2>&1; then
        if [ "$BIND_DEPENDENCY_STATE" = "repair" ]; then
            printf '%s\n' "opkg update && opkg install --force-reinstall bind-libs bind-dig"
        else
            printf '%s\n' "opkg update && opkg install bind-dig"
        fi
    elif command -v apk >/dev/null 2>&1; then
        if [ "$BIND_DEPENDENCY_STATE" = "repair" ]; then
            printf '%s\n' "apk update && apk fix --upgrade bind-libs bind-dig"
        else
            printf '%s\n' "apk update && apk add bind-dig"
        fi
    else
        printf '%s\n' "установите $BIND_DEPENDENCY_PACKAGES через пакетный менеджер прошивки"
    fi
}

install_update_dependencies() {
    log "Устанавливаю зависимости DNS-теста: $BIND_DEPENDENCY_PACKAGES"

    if command -v opkg >/dev/null 2>&1; then
        opkg update || fail "Не удалось обновить список пакетов opkg."
        if [ "$BIND_DEPENDENCY_STATE" = "repair" ]; then
            opkg install --force-reinstall bind-libs bind-dig || fail "Не удалось переустановить bind-libs и bind-dig."
        else
            opkg install bind-dig || fail "Не удалось установить bind-dig."
        fi
    elif command -v apk >/dev/null 2>&1; then
        apk update || fail "Не удалось обновить список пакетов apk."
        if [ "$BIND_DEPENDENCY_STATE" = "repair" ]; then
            apk fix --upgrade bind-libs bind-dig || fail "Не удалось переустановить bind-libs и bind-dig."
        else
            apk add bind-dig || fail "Не удалось установить bind-dig."
        fi
    else
        fail "Не найден поддерживаемый пакетный менеджер. $(dependency_install_hint)"
    fi

    command -v dig >/dev/null 2>&1 && dig -v >/dev/null 2>&1 ||
        fail "Пакеты установлены, но dig не запускается. Выполните: $(dependency_install_hint)"
    log "Зависимости DNS-теста готовы"
}

offer_update_dependencies() {
    [ -n "$INSTALLED_VERSION" ] || return 0

    detect_update_dependencies
    [ "$BIND_DEPENDENCY_STATE" != "ok" ] || return 0

    if [ "$BIND_DEPENDENCY_STATE" = "repair" ]; then
        log "Обнаружены несовместимые пакеты BIND: $BIND_DEPENDENCY_PACKAGES"
    else
        log "Для вкладки «Тест DNS» не хватает пакета: $BIND_DEPENDENCY_PACKAGES"
    fi

    case "$DEPENDENCY_MODE" in
        install)
            install_update_dependencies
            ;;
        skip)
            log "Установка зависимостей пропущена. Позже выполните: $(dependency_install_hint)"
            ;;
        *)
            answer=""
            if [ -c /dev/tty ] && printf 'Установить недостающие пакеты сейчас? [Y/n] ' >/dev/tty 2>/dev/null; then
                IFS= read -r answer </dev/tty 2>/dev/null || answer="n"
            else
                answer="n"
                log "Нет интерактивного терминала — зависимости не устанавливаю автоматически."
            fi
            case "$answer" in
                n|N|no|NO|нет|Нет|НЕТ)
                    log "Установка зависимостей пропущена. Позже выполните: $(dependency_install_hint)"
                    ;;
                *)
                    install_update_dependencies
                    ;;
            esac
            ;;
    esac
}

INSTALLED_VERSION="$(detect_installed_version || true)"
if [ -n "$INSTALLED_VERSION" ]; then
    if [ "$INSTALLED_VERSION" = "$VERSION" ]; then
        log "Уже установлена версия $VERSION — выполняю проверку и переустановку"
    else
        log "Обнаружена предыдущая версия: $INSTALLED_VERSION"
        log "Обновляю до версии $VERSION с сохранением пользовательских профилей в /etc"
    fi
else
    log "Предыдущая версия не обнаружена — чистая установка"
fi

# --- Проверки окружения -----------------------------------------------------

[ "$(id -u)" = "0" ] || fail "Нужны права root."

offer_update_dependencies

command -v ucode >/dev/null 2>&1 || fail "Не найден ucode. Установите пакет ucode."
command -v base64 >/dev/null 2>&1 || fail "Не найдена утилита base64."
command -v tar >/dev/null 2>&1 || fail "Не найдена утилита tar."
command -v sha256sum >/dev/null 2>&1 || fail "Не найдена утилита sha256sum."

if [ -x /usr/bin/tachyon ]; then
    BACKEND="Tachyon"
    BACKEND_VERSION="$(/usr/bin/tachyon show_version 2>/dev/null || echo unknown)"
elif [ -x /etc/init.d/homeproxy ]; then
    BACKEND="HomeProxy"
    if [ -r /var/run/homeproxy/core.info ] && command -v jsonfilter >/dev/null 2>&1; then
        BACKEND_VERSION="$(jsonfilter -i /var/run/homeproxy/core.info -e '@.version' 2>/dev/null || echo unknown)"
    else
        BACKEND_VERSION="unknown"
    fi
elif [ -x /usr/bin/forkop ]; then
    BACKEND="Forkop"
    BACKEND_VERSION="$(/usr/bin/forkop show_version 2>/dev/null || echo unknown)"
elif [ -x /usr/bin/podkop ]; then
    BACKEND="Podkop"
    BACKEND_VERSION="$(/usr/bin/podkop show_version 2>/dev/null || echo unknown)"
else
    fail "Не найден ни Tachyon, ни HomeProxy, ни Forkop, ни Podkop. Сначала установите один из поддерживаемых backend."
fi
log "Обнаружен $BACKEND $BACKEND_VERSION"

[ -d /www/luci-static/resources ] || fail "Не найдены ресурсы LuCI. Установите luci-base."

# --- Распаковка во временный каталог ----------------------------------------

TMP_DIR="$(mktemp -d /tmp/sing-box-service-check.XXXXXX)"
BACKUP_ARCHIVE="$TMP_DIR/rollback.tar"
TRANSACTION_ACTIVE=0

transaction_paths() {
    cat <<EOF
$BIN_PATH
$LEGACY_BIN_PATH
EOF
    # Runtime-файлы берём из самой распакованной нагрузки. Так новый файл не
    # сможет попасть в пакет, но выпасть из установки или отката.
    runtime_payload_paths "$TMP_DIR/usr/lib/sing-box-service-check" "$LIB_DIR"
    cat <<EOF
$SHARE_DIR/profiles.json
$SHARE_DIR/version
$SHARE_DIR/recovery.tar.gz
$SHARE_DIR/recovery.sha256
$VIEW_FILE
$OLD_CURRENT_VIEW_FILE
$PREVIOUS_VIEW_FILE
$OLDER_VIEW_FILE
$ANCIENT_VIEW_FILE
$HISTORIC_VIEW_FILE
$LEGACY_CACHE_VIEW_FILE
$OLDER_CACHE_VIEW_FILE
$EARLY_CACHE_VIEW_FILE
$OLDEST_CACHE_VIEW_FILE
$LEGACY_VIEW_FILE
$BROKEN_VIEW_FILE
$MENU_FILE
$ACL_FILE
EOF
}

begin_transaction() {
    backup_root="$TMP_DIR/rollback"
    mkdir -p "$backup_root"
    transaction_paths | while IFS= read -r path; do
        [ -n "$path" ] || continue
        if [ -f "$path" ]; then
            mkdir -p "$backup_root$(dirname "$path")"
            cp -p "$path" "$backup_root$path"
        fi
    done
    tar -cf "$BACKUP_ARCHIVE" -C "$backup_root" .
    TRANSACTION_ACTIVE=1
}

rollback_transaction() {
    log "Ошибка после начала установки — возвращаю предыдущую версию"
    transaction_paths | while IFS= read -r path; do
        [ -n "$path" ] && rm -f "$path"
    done
    tar -xf "$BACKUP_ARCHIVE" -C / 2>/dev/null || true
    clear_luci_cache
    reload_rpcd
}

cleanup() {
    status=$?
    trap - EXIT INT TERM
    if [ "$TRANSACTION_ACTIVE" = "1" ] && [ "$status" -ne 0 ]; then
        rollback_transaction
    fi
    rm -rf "$TMP_DIR"
    exit "$status"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

log "Распаковываю файлы"

